#include <vector>
#include <algorithm>

class Solution {
public:
    long long rob(std::vector<int>& nums) {
        long long s0 = 0, s1 = 0, s2 = 0;
        for (int x : nums) {
            long long new_s0 = std::max({s0, s1, s2});
            long long new_s1 = s0 + x;
            long long new_s2 = s1 + x;
            s0 = new_s0; s1 = new_s1; s2 = new_s2;
        }
        return std::max({s0, s1, s2});
    }
};

class Solution {
    public long rob(int[] nums) {
        long s0 = 0, s1 = 0, s2 = 0;
        for (int x : nums) {
            long newS0 = Math.max(s0, Math.max(s1, s2));
            long newS1 = s0 + x;
            long newS2 = s1 + x;
            s0 = newS0; s1 = newS1; s2 = newS2;
        }
        return Math.max(s0, Math.max(s1, s2));
    }
}

function rob(nums) {
    let s0 = 0, s1 = 0, s2 = 0;
    for (const x of nums) {
        const newS0 = Math.max(s0, s1, s2);
        const newS1 = s0 + x;
        const newS2 = s1 + x;
        s0 = newS0;
        s1 = newS1;
        s2 = newS2;
    }
    return Math.max(s0, s1, s2);
}
